//
// The standalone path: the six canonical files, embedded as raw bytes at build
// time and hashed here, in the browser. See `presets-source.ts` for why this
// exception to ADR 0021 decision 7(a) exists and what keeps it honest.
// ---------------------------------------------------------------------------

import { sha256Hex } from '../io/sha256';
import type { PresetSummary } from './client';
import type { PresetsSource } from './presets-source';

// `?raw` — the file's TEXT, exactly as it is on disk. `eager` so the module
// graph is static and Rollup can prove which files are involved; a dynamic glob
// would defeat `check-no-bundled-presets.mjs`, which reads the built output.
const RAW = import.meta.glob('../../../../protocols/presets/*.json', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/** `.../protocols/presets/live_singing.json` -> `live_singing`. */
function stemOf(path: string): string {
  const base = path.slice(path.lastIndexOf('/') + 1);
  return base.endsWith('.json') ? base.slice(0, -'.json'.length) : base;
}

interface Embedded {
  readonly id: string;
  readonly text: string;
  readonly parsed: Record<string, unknown>;
}

function embedded(): Embedded[] {
  return Object.entries(RAW)
    .map(([path, text]) => {
      const id = stemOf(path);
      const parsed = JSON.parse(text) as Record<string, unknown>;
      // Loader rule V1: `id` equals the basename. The backend's loader enforces
      // it server-side; nothing ran server-side here, so it is enforced here.
      if (parsed['id'] !== id) {
        throw new Error(
          `preset ${id}: rule V1 — the file's "id" is ${JSON.stringify(parsed['id'])}, ` +
            'which is not its own basename. The embedded copy disagrees with the canonical file.',
        );
      }
      return { id, text, parsed };
    })
    .sort((a, b) => a.id.localeCompare(b.id));
}

const FILES = embedded();
const TEXT = new Map(FILES.map((f) => [f.id, f.text]));

/** Bytes, not characters: the digest must be over what `sha256sum` would read. */
function utf8(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}

async function summaries(): Promise<readonly PresetSummary[]> {
  return Promise.all(
    FILES.map(async (file): Promise<PresetSummary> => {
      const bytes = utf8(file.text);
      return {
        id: file.id,
        sha256: await sha256Hex(bytes),
        name: String(file.parsed['name'] ?? file.id),
        targets: (file.parsed['targets'] as string[] | undefined) ?? [],
        bytes: bytes.byteLength,
        // No URL to fetch — the bytes are already here. Naming the canonical
        // path instead is the useful thing: it is what a reader would run
        // `sha256sum` against.
        url: `protocols/presets/${file.id}.json`,
      };
    }),
  );
}

export const bundledPresets: PresetsSource = {
  list: summaries,
  source: (id: string): Promise<string> => {
    const text = TEXT.get(id);
    return text === undefined
      ? Promise.reject(new Error(`no preset ${id} in this build`))
      : Promise.resolve(text);
  },
  capabilities: { backend: false },
  provenance:
    'embedded from protocols/presets/ at build time as raw bytes, hashed in this browser',
};
