//
// sha256, lowercase hex, in Node and in the browser.
//
// `crypto.subtle` is the Web Crypto API and is present in both (Node ≥ 19
// exposes it on `globalThis`), so the golden suite and the in-app
// golden-agreement readout of W2 hash with the SAME implementation. A Node-only
// `node:crypto` import would have made the digest row a property of the test
// runner rather than of the application.
//
// SECURE CONTEXT: `crypto.subtle` is undefined on an insecure origin that is
// not localhost — the same condition ADR 0021 decision 8 already requires for
// `navigator.mediaDevices`. The failure is therefore not a new one, and the
// message says so rather than reporting a bare TypeError.
// ----------------------------------------------------------------------------

function subtle(): SubtleCrypto {
  const c: Crypto | undefined = globalThis.crypto;
  if (c?.subtle === undefined) {
    throw new Error(
      'crypto.subtle is unavailable: this is an insecure origin that is not localhost (ADR 0021 decision 8 — ' +
        'phone-on-LAN needs the mkcert certificate), or a runtime older than Node 19',
    );
  }
  return c.subtle;
}

/** sha256 of `bytes`, lowercase hex — the form every manifest digest is written in. */
export async function sha256Hex(bytes: Uint8Array): Promise<string> {
  // Copied into a fresh, exactly-sized ArrayBuffer: `bytes` may be a view into
  // a larger buffer (a slice of a file read), and `digest` hashes the whole
  // buffer if handed one.
  const owned = new Uint8Array(bytes.byteLength);
  owned.set(bytes);
  const digest = await subtle().digest('SHA-256', owned.buffer);
  const out = new Uint8Array(digest);
  let hex = '';
  for (let i = 0; i < out.length; i += 1) {
    hex += (out[i] as number).toString(16).padStart(2, '0');
  }
  return hex;
}
